class NotesController < ApplicationController
  before_action { load_owner(params[:user_id]) }

  def destroy
    @owner.notes.find(params[:id]).destroy
  end

  private

  def load_owner(hashid)
    @owner = User.find(Hashids.new('salt').decode(hashid).first)
  end
end

